def get_operation():
    """Get user input for the operation to perform."""
    while True:
        operation = input("Choose operation: +, -, *, /: ").upper()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid input. Please choose +, -, *, or /.")

def get_numbers():
    """Get user input for the two numbers to perform the operation on."""
    while True:
        try:
            num1 = float(input("Number 1: "))
            num2 = float(input("Number 2: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers.")

def perform_operation(operation, num1, num2):
    """Perform the chosen operation on the two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        result = num1 / num2
    else:
        raise ValueError(f"Invalid operation: {operation}")
    return result

def main():
    operation = get_operation()
    num1, num2 = get_numbers()
    try:
        result = perform_operation(operation, num1, num2)
        print(f"The result of {num1} {operation} {num2} is {result}.")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
